def amicable_numbers_sum(n):
    proper_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        s = 0
        for d in range(1, int(i ** 0.5) + 1):
            if i % d == 0:
                s += d
                if d != i // d:
                    s += i // d
        proper_sum[i] = s - i

    total = 0
    for i in range(1, n + 1):
        j = proper_sum[i]
        if j > 0 and j <= n and proper_sum[j] == i:
            total += i
    return total
```

