def magic_square_test(matrix):
    if not matrix or not matrix[0]:
        return False
    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False

    nums = [x for row in matrix for x in row]
    if len(set(nums)) != n * n:
        return False
    if sorted(nums) != list(range(1, n * n + 1)):
        return False

    target = n * (n * n + 1) // 2
    row_sums = [sum(row) for row in matrix]
    col_sums = [sum(matrix[i][j] for i in range(n)) for j in range(n)]
    diag1 = sum(matrix[i][i] for i in range(n))
    diag2 = sum(matrix[i][n - 1 - i] for i in range(n))

    return all(s == target for s in row_sums + col_sums + [diag1, diag2])
```

