import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    def egcd(x, y):
        if y == 0:
            return 1, 0
        g, x1, y1 = egcd(y, x % y)
        return y1, x - (x // y) * y1

    ga, gb = abs(a), abs(b)
    x, y = egcd(ga, gb)
    if a < 0:
        x = -x
    if b < 0:
        y = -y

    g = math.gcd(ga, gb)
    if n % g != 0:
        return None

    x *= n // g
    y *= n // g

    x = x % gb
    y = (n - a * x) // b
    return (x, y)
```

