def max_sum_increasing_subseq(arr, n, i, k):
    target = arr[k]
    dp = [0] * i
    for j in range(i):
        if arr[j] < target:
            dp[j] = arr[j]
            for t in range(j):
                if arr[t] < arr[j] and arr[t] < target:
                    dp[j] = max(dp[j], dp[t] + arr[j])
    return max(dp) + target
